CREATE TABLE IF NOT EXISTS creator_course_details (course_id BIGINT UNSIGNED PRIMARY KEY,metadata LONGTEXT NOT NULL, FOREIGN KEY(course_id) REFERENCES creator_courses(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS creator_course_reviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,course_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,score TINYINT UNSIGNED NOT NULL,recommend TINYINT NOT NULL,body TEXT NOT NULL,locale VARCHAR(2) NOT NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(course_id,user_id),FOREIGN KEY(course_id) REFERENCES creator_courses(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS creator_course_questions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,course_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,parent_id BIGINT UNSIGNED NULL,body TEXT NOT NULL,locale VARCHAR(2) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(course_id,locale),FOREIGN KEY(course_id) REFERENCES creator_courses(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS creator_course_reactions (course_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,reaction TINYINT NOT NULL,PRIMARY KEY(course_id,user_id),FOREIGN KEY(course_id) REFERENCES creator_courses(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS creator_course_reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,course_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,body TEXT NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'pending',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(course_id) REFERENCES creator_courses(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS creator_course_schedules (course_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,starts_at DATETIME NOT NULL,PRIMARY KEY(course_id,user_id),FOREIGN KEY(course_id) REFERENCES creator_courses(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;